<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { api,json } from '../../api/client'
import { useAuth } from '../../stores/auth'
import type { WorkspacePreferences,WorkspaceMode } from '../../types'
const auth=useAuth(),prefs=ref<WorkspacePreferences>(),selected=ref<string[]>([]),mode=ref<WorkspaceMode>('simple'),error=ref(''),success=ref(''),busy=ref(false)
onMounted(async()=>{try{prefs.value=await api('/workspace/preferences');selected.value=[...prefs.value!.enabled_modules];mode.value=prefs.value!.mode}catch(e){error.value=(e as Error).message}})
function preset(value:'simple'|'advanced'){mode.value=value;selected.value=[...(prefs.value?.presets[value]||[])];success.value=''}
function custom(){mode.value='custom';success.value=''}
async function save(){busy.value=true;error.value='';success.value='';try{prefs.value=await api('/workspace/preferences',json('PUT',{mode:mode.value,enabled_modules:selected.value}));if(auth.user){auth.user.workspace_mode=prefs.value!.mode;auth.user.enabled_modules=[...prefs.value!.enabled_modules]}success.value='Your workspace layout is saved. Existing records and team permissions are unchanged.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR WORKSPACE</span><h1>Choose your modules</h1><p class="muted">Start simple, show all available tools, or choose exactly what you use.</p></div></div><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p><form v-if="prefs" @submit.prevent="save" class="panel form-panel"><h2>Start with a mode</h2><div class="module-presets"><button type="button" class="button" :class="mode==='simple'?'primary':'secondary'" :aria-pressed="mode==='simple'" @click="preset('simple')">Simple mode</button><button type="button" class="button" :class="mode==='advanced'?'primary':'secondary'" :aria-pressed="mode==='advanced'" @click="preset('advanced')">Advanced mode</button><span v-if="mode==='custom'" class="chip">Custom selection</span></div><p class="muted">Simple mode keeps invoicing, clients and quotations close at hand. Advanced shows all modules available to your role. Choosing checkboxes creates a custom layout.</p><section class="spaced"><h2>Always available</h2><p>Overview, invoices, clients and this module selector. Business settings and platform administration still follow your role.</p></section><div class="module-grid spaced"><label v-for="item in prefs.modules" :key="item.id" class="module-card"><input type="checkbox" v-model="selected" :value="item.id" @change="custom"><span><strong>{{ item.name }}</strong><small>{{ item.description }}</small></span></label></div><p class="muted spaced">These preferences belong only to you. Hiding a module never deletes records or turns off existing scheduled work. You can re-enable it here. Module selection does not grant additional permissions.</p><button class="button primary spaced" :disabled="busy">{{ busy?'Saving…':'Save my modules' }}</button></form></template>
